arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1956_03.json') as f:
    data = json.load(f)

# Print keys
def print_keys(d, indent=0):
    if isinstance(d, dict):
        for k in list(d.keys())[:20]:
            print('  ' * indent + k)
        for k, v in d.items():
            if isinstance(v, (dict, list)):
                print_keys(v, indent+1)
    elif isinstance(d, list) and d and isinstance(d[0], dict):
        print('  ' * indent + '[list with ' + str(len(d)) + ' items]')

print_keys(data)
"
